public class Student {
    private String name;
    private int age;

    public void setAge(int age) {
        if (age < 0 || age > 150) {
            throw new IllegalArgumentException("年龄不合法");
        }
        this.age = age;
    }

    public int getAge() {
        return age;
    }
}

-- 在 name 字段建索引
CREATE INDEX idx_student_name ON student(name);

-- 查看执行计划，重点看 type 和 rows
EXPLAIN SELECT * FROM student WHERE name = '张三';

.container {
  display: flex;
  justify-content: space-between;  /* 主轴对齐 */
  align-items: center;            /* 交叉轴对齐 */
  gap: 16px;                      /* 间距，比 margin 更好用 */
}

.list {
  display: flex;
  flex-wrap: wrap;   /* 放不下就换行 */
  gap: 24px;
}

.item {
  flex: 1 1 300px;   /* 最小 300px，有空间就拉伸 */
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}

@media (max-width: 900px) {
  .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 600px) {
  .grid { grid-template-columns: minmax(0, 1fr); }
}

const request = axios.create({
  baseURL: '/api',
  timeout: 10000
})

request.interceptors.response.use(
  (response) => {
    const res = response.data
    if (res.code === 0 || res.code === 200) return res.data
    return Promise.reject(new Error(res.message || '接口异常'))
  },
  (error) => {
    let message = '网络异常，请稍后重试'
    if (error.code === 'ECONNABORTED') message = '请求超时'
    else if (error.response) message = `请求失败（HTTP ${error.response.status}）`
    return Promise.reject(new Error(message))
  }
)

